args.new_string:
import { connection } from 'next/server';

export default async function Home() {
  // Use connection() to opt out of static prerendering
  // This ensures the component renders dynamically on each request
  await connection();

  // Now we can use Date.now() and it will be different on each request
  const timestamp = new Date().toISOString();
  const unixTimestamp = Date.now();

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>Current server time: <strong>{timestamp}</strong></p>
      <p>Unix timestamp: <strong>{unixTimestamp}</strong></p>
      <p style={{ marginTop: '2rem', color: '#666', fontSize: '0.9rem' }}>
        Refresh the page to see the timestamp update with each request.
      </p>
    </main>
  );
}

